const LANGS=['en','ru','tr','de','pl'];
const $=(s,r=document)=>r.querySelector(s), $$=(s,r=document)=>[...r.querySelectorAll(s)];
const esc=s=>String(s??'').replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[m]));
const norm=s=>String(s??'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase().replace(/&amp;/g,'&').replace(/[^a-z0-9а-яёğüşöçıİąćęłńóśźż\s+€-]/gi,' ').replace(/\s+/g,' ').trim();
const lang=()=>{const x=(localStorage.getItem('atoLanguage')||document.documentElement.lang||'en').slice(0,2);return LANGS.includes(x)?x:'en'};

